package airgap

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

// WriteMirrorCommands emits mirror-commands.sh with connected and disconnected examples.
func WriteMirrorCommands(opts Options, outputDir string) error {
	const script = `#!/usr/bin/env bash
# Generated by patternizer airgap init
# Requires: oc-mirror plugin v2, pull credentials for source registries
set -euo pipefail

REGISTRY="{{.Registry}}"
HERE="$(cd "$(dirname "$0")" && pwd)"
CONFIG="${HERE}/imagesetconfig.yaml"
REGISTRIES_D="${HERE}/registries.d"
CACHE="${OC_MIRROR_CACHE:-${HOME}/.cache/oc-mirror}"
WORKSPACE="${CACHE}/workspace"

# Disable sigstore attachments for registry.connect.redhat.com (Vault / partner images).
mkdir -p "${REGISTRIES_D}"
cat > "${REGISTRIES_D}/registry.connect.redhat.com.yaml" <<'EOF'
docker:
  registry.connect.redhat.com:
    use-sigstore-attachments: false
EOF

mkdir -p "${CACHE}" "${WORKSPACE}"

echo "==> Mirror to registry (partially disconnected / bastion with registry access)"
echo oc mirror --config="${CONFIG}" --workspace "file://${WORKSPACE}" "docker://${REGISTRY}" --v2 --registries.d="${REGISTRIES_D}"
echo
echo "==> Fully disconnected: mirror to disk, then from disk to registry"
echo "# On connected host:"
echo oc mirror --config="${CONFIG}" "file://${CACHE}/mirror" --v2 --registries.d="${REGISTRIES_D}"
echo "# Transfer ${CACHE}/mirror to the disconnected host, then:"
echo oc mirror --from "file://${CACHE}/mirror" "docker://${REGISTRY}" --v2
echo
echo "==> After mirroring, apply generated cluster resources (paths may vary by oc-mirror version):"
echo "cd ${WORKSPACE}/working-dir/cluster-resources"
echo "oc apply -f idms-oc-mirror.yaml -f itms-oc-mirror.yaml"
echo "oc apply -f cs-redhat-operator-index-v{{.DashVersion}}.yaml"
echo "oc apply -f cs-community-operator-index-v{{.DashVersion}}.yaml"
echo "# Also apply marketplace CatalogSource YAML if present"
echo
echo "==> Deploy the pattern from a host that can reach the disconnected cluster and Git:"
echo "export PATTERN_DISCONNECTED_HOME=${REGISTRY}/validatedpatterns"
echo "./pattern.sh make install"
`

	tmpl, err := template.New("mirror").Parse(script)
	if err != nil {
		return err
	}
	path := filepath.Join(outputDir, "mirror-commands.sh")
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o755)
	if err != nil {
		return err
	}
	defer f.Close()

	return tmpl.Execute(f, map[string]string{
		"Registry":    opts.Registry,
		"DashVersion": dashVersion(opts.OCPVersion),
	})
}

// WriteChecklist emits CHECKLIST.md covering secrets, pull secrets, Git, and CatalogSources.
func WriteChecklist(inv *PatternInventory, opts Options, outputDir string) error {
	var b strings.Builder
	b.WriteString("# Airgap init checklist\n\n")
	b.WriteString(fmt.Sprintf("Pattern: **%s**  \n", inv.PatternName))
	b.WriteString(fmt.Sprintf("OCP version: **%s**  \n", opts.OCPVersion))
	b.WriteString(fmt.Sprintf("Mirror registry: **%s**  \n\n", opts.Registry))

	b.WriteString("## 1. Mirror-host pull secrets (connected bastion)\n\n")
	b.WriteString("Ensure `~/.docker/config.json` / `auth.json` can pull from every source registry referenced in `imagesetconfig.yaml`:\n\n")
	b.WriteString("- [ ] `registry.redhat.io`\n")
	b.WriteString("- [ ] `registry.connect.redhat.com` (Vault and partner images)\n")
	b.WriteString("- [ ] `quay.io` (Validated Patterns charts and containers)\n")
	b.WriteString("- [ ] `ghcr.io` (external-secrets images, if used)\n")
	b.WriteString("- [ ] `docker.io` / `registry.access.redhat.com` as needed\n")
	b.WriteString("- [ ] Review oc-mirror logs for skipped `oci://` related images and add them to `additionalImages`\n\n")

	b.WriteString("## 2. Run mirroring\n\n")
	b.WriteString("- [ ] Run commands in `mirror-commands.sh`\n")
	b.WriteString("- [ ] Apply IDMS/ITMS and CatalogSource manifests from the oc-mirror workspace\n")
	b.WriteString("- [ ] Do **not** rename generated CatalogSource names\n\n")

	b.WriteString("## 3. Cluster registry trust\n\n")
	b.WriteString("- [ ] Cluster nodes trust the mirror registry CA\n")
	b.WriteString("- [ ] Global pull secret can authenticate to the internal registry if required\n\n")

	b.WriteString("## 4. Pattern values for disconnected use\n\n")
	b.WriteString("- [ ] Merge `values-disconnected.yaml` into the pattern (or commit overlays)\n")
	b.WriteString(fmt.Sprintf("- [ ] `main.multiSourceConfig.helmRepoUrl` → `%s/validatedpatterns`\n", opts.Registry))
	b.WriteString(fmt.Sprintf("- [ ] `main.patternsOperator.source` → `%s`\n", CatalogSourceName(CatalogCommunity, opts.OCPVersion)))
	b.WriteString(fmt.Sprintf("- [ ] `main.gitops.operatorSource` → `%s`\n", CatalogSourceName(CatalogRedHat, opts.OCPVersion)))
	b.WriteString("- [ ] Per-subscription `source:` fields point at mirrored catalogs\n")
	b.WriteString(fmt.Sprintf("- [ ] `export PATTERN_DISCONNECTED_HOME=%s/validatedpatterns` before `./pattern.sh make install`\n\n", opts.Registry))

	b.WriteString("## 5. Git reachability\n\n")
	b.WriteString("- [ ] Pattern Git repository is hosted inside the disconnected network\n")
	b.WriteString("- [ ] `git remote -v` on the install host points at the disconnected Git server\n")
	b.WriteString("- [ ] (oc-mirror does **not** mirror Git content)\n\n")

	b.WriteString("## 6. Secrets (Vault + External Secrets Operator)\n\n")
	b.WriteString("Secrets are **not** mirrored. Keep the existing Validated Patterns secrets workflow:\n\n")
	b.WriteString("- [ ] Mirror Vault / ESO operators and operand images (included when those charts/subscriptions are present)\n")
	b.WriteString("- [ ] On a trusted host **inside** the airgap, create `values-secret.yaml` from `values-secret.yaml.template`\n")
	b.WriteString("- [ ] Prefer `onMissingValue: generate` so fewer secrets must cross the air gap\n")
	b.WriteString("- [ ] Run `./pattern.sh make load-secrets` after install (uses `rhvp.cluster_utils.load_secrets`)\n")
	b.WriteString("- [ ] Never commit real `values-secret.yaml` to Git\n")
	b.WriteString("- [ ] External backends (AWS SM, Azure KV, SaaS Vault) will **not** work without egress — use in-cluster Vault\n\n")

	if len(inv.ManagedClusterGroups) > 0 {
		b.WriteString("## 7. Managed / spoke clusters\n\n")
		b.WriteString("This pattern declares managedClusterGroups: " + strings.Join(inv.ManagedClusterGroups, ", ") + "\n\n")
		b.WriteString("- [ ] Include spoke values files in init (`--cluster-groups`)\n")
		b.WriteString("- [ ] Ensure spoke operators (e.g. GitOps via ACM policies) are present in the ImageSetConfig\n")
		b.WriteString("- [ ] Spokes must also trust the mirror registry and use IDMS/ITMS\n\n")
	}

	b.WriteString("## Discovery warnings\n\n")
	if len(inv.Warnings) == 0 {
		b.WriteString("_No warnings emitted during discovery._\n")
	} else {
		for _, w := range inv.Warnings {
			b.WriteString(fmt.Sprintf("- %s\n", w))
		}
	}

	b.WriteString("\n## Generated operators\n\n")
	for _, op := range inv.Operators {
		ch := op.Channel
		if ch == "" {
			ch = "(default channel)"
		}
		b.WriteString(fmt.Sprintf("- `%s` channel `%s` [%s]\n", op.Name, ch, op.Catalog))
	}

	b.WriteString("\n## Generated remote charts (OCI)\n\n")
	for _, rc := range inv.RemoteCharts {
		b.WriteString(fmt.Sprintf("- `%s` (%s → %s) → `%s`\n", rc.Name, rc.VersionConstraint, rc.ResolvedVersion, rc.PullSpec))
		for _, img := range rc.Images {
			b.WriteString(fmt.Sprintf("  - image: `%s`\n", img))
		}
	}

	b.WriteString("\n## Generated local charts\n\n")
	for _, lc := range inv.LocalCharts {
		b.WriteString(fmt.Sprintf("- `%s` path `%s` (%d images)\n", lc.Name, lc.Path, len(lc.Images)))
	}

	return os.WriteFile(filepath.Join(outputDir, "CHECKLIST.md"), []byte(b.String()), 0o644)
}
